CREATE POLICY offsite_arquivos_ler ON storage.objects FOR SELECT TO authenticated USING(bucket_id='pre-offsite-materiais' AND (public.offsite_admin() OR EXISTS(SELECT 1 FROM public.offsite_materiais m WHERE m.arquivo_path=name AND public.offsite_cadeira() IS NOT NULL AND (m.cadeira_id IS NULL OR m.cadeira_id=public.offsite_cadeira()))));
CREATE POLICY offsite_arquivos_admin ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='pre-offsite-materiais' AND public.offsite_admin());
CREATE POLICY offsite_arquivos_remover ON storage.objects FOR DELETE TO authenticated USING(bucket_id='pre-offsite-materiais' AND public.offsite_admin());
CREATE FUNCTION public.offsite_config_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF jsonb_typeof(NEW.conteudo)<>'object' OR octet_length(NEW.conteudo::text)>1000000 THEN RAISE EXCEPTION 'Configuração inválida'; END IF; NEW.atualizado_em:=now(); INSERT INTO offsite_historico(ator,acao,antes,depois) VALUES(auth.uid(),'configuracao',CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); RETURN NEW; END $$;
CREATE TRIGGER offsite_config_audit BEFORE INSERT OR UPDATE ON public.offsite_config FOR EACH ROW EXECUTE FUNCTION public.offsite_config_guard();